/* View-only module lab: contract decisions are generated by Python, not duplicated here. */
(() => {
  'use strict';
  if (document.body.dataset.page !== 'swap') return;
  const familySelect = document.getElementById('lab-workflow');
  const slotBox = document.getElementById('lab-slots');
  const verdict = document.getElementById('lab-verdict');
  const summary = document.getElementById('lab-summary');
  const diagnostics = document.getElementById('lab-diagnostics');
  const connections = document.getElementById('lab-connections');
  const instructions = document.getElementById('lab-instructions');
  let workflows = [];
  let active;

  const statusText = {
    compatible: ['Declared contracts match', 'Port schemas and declared fingerprints agree. Runtime behavior and numerical equivalence are not established.'],
    unverified: ['Artifact verification needed', 'The interfaces match, but required external model artifacts or fingerprints remain unresolved.'],
    migration: ['Migration or retraining needed', 'A learned representation or artifact fingerprint is incompatible with the selected module.'],
    incompatible: ['Incompatible connection', 'A category, required slot or semantic port contract does not match.']
  };

  function inspect() {
    const ids = active.slots.map(slot => document.getElementById('slot-' + slot.name).value);
    const report = active.cases[JSON.stringify(ids)];
    if (!report) { verdict.textContent = 'Not in this reference demonstration'; return; }
    const [title, detail] = statusText[report.status];
    verdict.textContent = title;
    verdict.dataset.status = report.status;
    summary.textContent = detail;
    diagnostics.replaceChildren();
    for (const issue of report.diagnostics) {
      const p = document.createElement('p');
      p.className = 'lab-issue'; p.textContent = issue.message;
      diagnostics.append(p);
    }
    connections.replaceChildren();
    for (const link of report.connections) {
      const node = document.createElement('div');
      node.className = 'lab-connection ' + (link.matches ? 'match' : 'mismatch');
      const name = document.createElement('strong'); name.textContent = `${link.from} → ${link.to}`;
      const schema = document.createElement('span');
      schema.textContent = link.matches ? link.actual : `${link.actual} ≠ ${link.expected}`;
      node.append(name, schema); connections.append(node);
    }
    if (!report.connections.length) {
      const p = document.createElement('p'); p.textContent = 'No resolvable ports for these selections.';
      connections.append(p);
    }
  }
  function selectFamily() {
    active = workflows.find(x => x.id === familySelect.value);
    if (!active) return;
    instructions.textContent = active.subtitle;
    slotBox.replaceChildren();
    for (const slot of active.slots) {
      const label = document.createElement('label'); label.className = 'lab-label';
      label.htmlFor = 'slot-' + slot.name;
      label.textContent = `${slot.name.replaceAll('_', ' ')} (${slot.category})`;
      const select = document.createElement('select');
      select.className = 'lab-select'; select.id = 'slot-' + slot.name;
      for (const option of slot.options) {
        const el = document.createElement('option'); el.value = option.id;
        el.textContent = option.label; select.append(el);
      }
      select.value = active.defaults[slot.name] || '';
      select.addEventListener('change', inspect);
      slotBox.append(label, select);
    }
    inspect();
  }
  document.getElementById('lab-reset').addEventListener('click', selectFamily);
  familySelect.addEventListener('change', selectFamily);
  fetch('data/compatibility.json')
    .then(response => { if (!response.ok) throw Error('Reference data could not be loaded'); return response.json(); })
    .then(data => {
      workflows = data.workflows;
      for (const workflow of workflows) {
        const option = document.createElement('option'); option.value = workflow.id;
        option.textContent = workflow.title; familySelect.append(option);
      }
      selectFamily();
    })
    .catch(error => {verdict.textContent = error.message;});
})();
